/**
 * @summary Read persisted candle-evidence reviews for settled trades
 */
export const getListTradeReviewsUrl = (params?: ListTradeReviewsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/journal/reviews?${stringifiedParams}`
    : `/api/journal/reviews`;
};

export const listTradeReviews = async (
  params?: ListTradeReviewsParams,
  options?: RequestInit,
): Promise<TradeReview[]> => {
  return customFetch<TradeReview[]>(getListTradeReviewsUrl(params), {
    ...options,
    method: "GET",
  });
};

