/**
 * @summary Read persisted per-concept and per-symbol closed-trade performance
 */
export const getListTradePerformanceUrl = (
  params?: ListTradePerformanceParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/journal/performance?${stringifiedParams}`
    : `/api/journal/performance`;
};

export const listTradePerformance = async (
  params?: ListTradePerformanceParams,
  options?: RequestInit,
): Promise<TradePerformance[]> => {
  return customFetch<TradePerformance[]>(getListTradePerformanceUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListTradePerformanceQueryKey = (
  params?: ListTradePerformanceParams,
) => {
  return [`/api/journal/performance`, ...(params ? [params] : [])] as const;
};

